<script setup lang="ts">
import { caseStudies } from '~/data/caseStudies'

const { category } = useUiState()
const filters = [
  { id: 'all', label: 'All Projects' },
  { id: 'architecture', label: 'System Architecture' },
  { id: 'opensource', label: 'Open Source' },
  { id: 'fullstack', label: 'Full-Stack' }
] as const

const filtered = computed(() =>
  category.value === 'all'
    ? caseStudies
    : caseStudies.filter((p) => p.categories.includes(category.value))
)
</script>

<template>
  <main class="mx-auto min-h-screen max-w-6xl space-y-10 px-6 pb-24 pt-16">
    <section class="mb-12 flex flex-col justify-between gap-8 md:flex-row md:items-end">
      <PageHeader title="Engineered" accent="Systems." />
      <div class="flex flex-wrap gap-2 font-mono text-[10px] uppercase tracking-wider">
        <button
          v-for="f in filters"
          :key="f.id"
          type="button"
          class="rounded-lg px-4 py-2 font-bold"
          :class="category === f.id ? 'bg-primary text-on-primary' : 'border border-outline-variant/20 bg-surface-container text-on-surface-variant'"
          @click="category = f.id"
        >
          {{ f.label }}
        </button>
      </div>
    </section>

    <section class="grid grid-cols-1 gap-6 md:grid-cols-2">
      <article v-for="project in filtered" :key="project.id" class="overflow-hidden rounded-xl border border-outline-variant/10 bg-surface-container p-8">
        <span class="mb-2 block font-mono text-[10px] uppercase tracking-[0.2em] text-secondary">{{ project.eyebrow }}</span>
        <h3 class="font-headline text-2xl font-bold text-on-surface">{{ project.title }}</h3>
        <div class="my-6 grid grid-cols-2 gap-6">
          <div><p class="text-[10px] uppercase text-on-surface-variant/60">Problem</p><p class="text-sm text-on-surface-variant">{{ project.problem }}</p></div>
          <div><p class="text-[10px] uppercase text-on-surface-variant/60">Solution</p><p class="text-sm text-on-surface-variant">{{ project.solution }}</p></div>
        </div>
        <p class="font-mono text-xs text-secondary">{{ project.impactLabel }}: {{ project.impactValue }}</p>
      </article>
    </section>
  </main>
</template>
